with feeders as (
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , MEM_STATUS as MEMBER_STATUS
        , cast(null as varchar) as JOINING_TYPE
        , cast(null as varchar) as MEMBER_SUM_INSURED
        , cast(null as varchar) as MEMBER_PREMIUM
        , cast(null as varchar) as RELATIONSHIP_TO_PRIMARY
        , cast(null as varchar) as EXIT_REASON
        , cast(null as varchar) as COVERAGE_START_DATE
        , cast(null as varchar) as ENROLMENT_DATE
        , cast(null as varchar) as COVERAGE_END_DATE
        , 'BA_HCP_DT_MEM' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_mem') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , MEM_STATUS as MEMBER_STATUS
        , MEM_ADD_FLAG as JOINING_TYPE
        , cast(null as varchar) as MEMBER_SUM_INSURED
        , cast(null as varchar) as MEMBER_PREMIUM
        , cast(null as varchar) as RELATIONSHIP_TO_PRIMARY
        , cast(null as varchar) as EXIT_REASON
        , cast(null as varchar) as COVERAGE_START_DATE
        , cast(null as varchar) as ENROLMENT_DATE
        , cast(null as varchar) as COVERAGE_END_DATE
        , 'BA_HCP_DT_MEM_COV' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_mem_cov') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__CONTRACT_ID))) as HUB_POLICY_HK
        , MEM_STATUS as MEMBER_STATUS
        , MEM_ADD_FLAG as JOINING_TYPE
        , cast(null as varchar) as MEMBER_SUM_INSURED
        , cast(null as varchar) as MEMBER_PREMIUM
        , cast(null as varchar) as RELATIONSHIP_TO_PRIMARY
        , cast(null as varchar) as EXIT_REASON
        , cast(null as varchar) as COVERAGE_START_DATE
        , cast(null as varchar) as ENROLMENT_DATE
        , cast(null as varchar) as COVERAGE_END_DATE
        , 'BA_HCP_DT_POL_COV' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hcp_dt_pol_cov') }}
    where (nullif(trim(CONTRACT_ID),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_NO))) as HUB_POLICY_HK
        , cast(null as varchar) as MEMBER_STATUS
        , cast(null as varchar) as JOINING_TYPE
        , SUM_INUSRED as MEMBER_SUM_INSURED
        , ANNUAL_PREMIUM as MEMBER_PREMIUM
        , DWH_RELATIONSHIP as RELATIONSHIP_TO_PRIMARY
        , cast(null as varchar) as EXIT_REASON
        , cast(null as varchar) as COVERAGE_START_DATE
        , cast(null as varchar) as ENROLMENT_DATE
        , cast(null as varchar) as COVERAGE_END_DATE
        , 'BGIL_GMC_FINAL_INSTL_DATA' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_bgil_gmc_final_instl_data') }}
    where (nullif(trim(POLICY_NO),'')) is not null
    union all
    select
        md5(upper('HUB_POLICY|' || (HUB_POLICY_BK__POLICY_REF))) as HUB_POLICY_HK
        , cast(null as varchar) as MEMBER_STATUS
        , cast(null as varchar) as JOINING_TYPE
        , SUM_INSURED as MEMBER_SUM_INSURED
        , cast(null as varchar) as MEMBER_PREMIUM
        , cast(null as varchar) as RELATIONSHIP_TO_PRIMARY
        , cast(null as varchar) as EXIT_REASON
        , cast(null as varchar) as COVERAGE_START_DATE
        , cast(null as varchar) as ENROLMENT_DATE
        , cast(null as varchar) as COVERAGE_END_DATE
        , 'BJAZ_CARD_DTLS' as RECORD_SOURCE
        , 'opus_health_legacy_v4' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_card_dtls') }}
    where (nullif(trim(POLICY_REF),'')) is not null
