resolved as (
    select
        HUB_POLICY_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_STATUS end) as MEMBER_STATUS,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then JOINING_TYPE end) as JOINING_TYPE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_SUM_INSURED end) as MEMBER_SUM_INSURED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then MEMBER_PREMIUM end) as MEMBER_PREMIUM,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then RELATIONSHIP_TO_PRIMARY end) as RELATIONSHIP_TO_PRIMARY,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then EXIT_REASON end) as EXIT_REASON,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_START_DATE end) as COVERAGE_START_DATE,
        coalesce(max(case when SOURCE_RUN = 'opus_health_v2' then ENROLMENT_DATE end),
                 max(case when SOURCE_RUN = 'opus_health_legacy_v4' then ENROLMENT_DATE end)) as ENROLMENT_DATE,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then COVERAGE_END_DATE end) as COVERAGE_END_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_POLICY_HK
),

hashed as (
    select
        *,
        case when MEMBER_STATUS is not null or JOINING_TYPE is not null or MEMBER_SUM_INSURED is not null or MEMBER_PREMIUM is not null or RELATIONSHIP_TO_PRIMARY is not null or EXIT_REASON is not null or COVERAGE_START_DATE is not null or ENROLMENT_DATE is not null or COVERAGE_END_DATE is not null
                     then md5(upper(coalesce(cast(MEMBER_STATUS as varchar), '') || '|' || coalesce(cast(JOINING_TYPE as varchar), '') || '|' || coalesce(cast(MEMBER_SUM_INSURED as varchar), '') || '|' || coalesce(cast(MEMBER_PREMIUM as varchar), '') || '|' || coalesce(cast(RELATIONSHIP_TO_PRIMARY as varchar), '') || '|' || coalesce(cast(EXIT_REASON as varchar), '') || '|' || coalesce(cast(COVERAGE_START_DATE as varchar), '') || '|' || coalesce(cast(ENROLMENT_DATE as varchar), '') || '|' || coalesce(cast(COVERAGE_END_DATE as varchar), '')))
                end as SAT_POLICY_CERTIFICATE_HASHDIFF
    from resolved
)

select * from hashed
where HUB_POLICY_HK is not null
  and SAT_POLICY_CERTIFICATE_HASHDIFF is not null
